from ta_uexgate.uexgate_cmds import uexgate_group_cmds_params
from functools import partial
from copy import deepcopy
import sys
import re
import shutil
import os

if sys.version_info.major == 2:
    Atom = str
else:
    from term import Atom

range_regex = r'^(?P<start>\d+)\.\.(?P<stop>\d+)$'


def encode_strings(container):
    """
    Encode all strings into bytes
    :param container:
    :return:
    """
    return convert_items(container, [(lambda item: isinstance(item, str) and not isinstance(item, Atom), str.encode)])


def decode_bytes(container):
    """
    Decode all bytes into strings
    :param container:
    :return:
    """
    return convert_items(container, [(lambda item: isinstance(item, bytes), bytes.decode)])


def convert_items(container, condition_func_to_convert_func_map):
    """
    Convert items by specified rules
    Supported collections: list, dict, tuple
    :param container:
    :param condition_func_to_convert_func_map: list of tuple
    :return:
    """
    for condition_func, convert_func in condition_func_to_convert_func_map:
        if condition_func(container):
            return convert_func(container)
    if isinstance(container, list):
        _call_on_list_items(container, partial(convert_items, condition_func_to_convert_func_map=condition_func_to_convert_func_map))
    elif isinstance(container, dict):
        _call_on_dict_keys_and_values(container, partial(convert_items, condition_func_to_convert_func_map=condition_func_to_convert_func_map))
    elif isinstance(container, tuple):
        return tuple(convert_items(list(container), condition_func_to_convert_func_map))
    return container


def _call_on_list_items(container, func):
    for index, item in enumerate(container):
        container[index] = func(item)


def _call_on_dict_keys_and_values(container, func):
    keys = deepcopy(list(container.keys()))
    for key in keys:
        new_key = func(key)
        new_value = func(container[key])
        if new_key != key:
            del container[key]
            container[new_key] = new_value
        else:
            container[key] = new_value
    # for key, item in container.items():
    #     container[key] = func(item)


def convert_elixir_range(item):
    """
    Convert elixir style range string into tuple or list
    :param item:
    :return:
    """
    match = re.search(range_regex, item)
    return_tuple = (Atom('range'), int(match.group('start')), int(match.group('stop')))
    if sys.version_info.major == 2:
        return list(return_tuple)
    return return_tuple


def _sort_and_join_kw_list(group_params, groups):
    """
    Sort the params in groups according to the order of params in group_params list and join the groups insto single kw list
    :param item:
    :return:
    """
    output = []
    for _, group_kw_list in groups.items():
        index_keyval = []
        for (key, value) in group_kw_list:
            index_keyval.append((group_params.index(str(key)), (key, value)))
        index_keyval.sort()
        sorted_kw_list = [keyval for index, keyval in index_keyval]
        output += sorted_kw_list
    return output


def _put_to_groups(group_params, kw_list):
    """
    Put keywords to groups based on _X suffix
    :param item:
    :return:
    """
    output_kw_list = []
    groups = {}
    for key, value in kw_list:
        ktype = type(key)
        match = re.search(r'^(.*)_(\d+)$', str(key))
        if match and match.group(1) not in group_params:
            raise ValueError("parameter {} is not a group parameter and cannot be suffixed with _X".format(match.group(1)))
        elif match:
            param = match.group(1)
            group_id = int(match.group(2))
        else:
            param = str(key)
            group_id = None
        if param in group_params:
            group_kw_list = groups.get(group_id, [])
            if param in [str(k) for (k, _) in group_kw_list]:
                raise ValueError("parameter {} was defined for a group {} more than once".format(param, group_id))
            group_kw_list.append((ktype(param), value))
            groups[group_id] = group_kw_list
        else:
            output_kw_list.append((key, value))
    return output_kw_list, groups


def sort_keys_if_needed(cmd, kw_list):
    """
    Sort keyword list elements for specific commands that use grouped params
    :param item:
    :return:
    """
    if (str(cmd)) in uexgate_group_cmds_params:
        group_params = uexgate_group_cmds_params[str(cmd)]
        output_kw_list, groups = _put_to_groups(group_params, kw_list)
        if None in groups and len(groups) >= 2:
            raise ValueError("group parameters with _X suffix (indicating usage of multiple groups)"
                             " cannot't be mixed with parameters without _X suffix (indicating usage of a single group)")
        return output_kw_list + _sort_and_join_kw_list(group_params, groups)
    else:
        return kw_list


def compress_logs(path):
    shutil.make_archive(base_name=os.path.join(path, 'uex_logs'),
                        format='zip',
                        base_dir='uex_logs',
                        root_dir=path)
    shutil.rmtree(os.path.join(path, 'uex_logs'))


def verify_if_test_sr_or_regression():  # noqa: C901

    path1 = '/home/ute/testline_init_results/logs/env_variables.txt'
    path2 = '/home/ute/testline_init_results/execution/logs/env_variables.txt'

    correct_matches = ('app_cloud_singlerun', 'app_cloud_regression')
    paths = [path1, path2]
    try:
        for path in paths:
            if not os.path.exists(path):
                continue

            with open(path, mode='r', encoding='utf-8') as f:
                for line in f:
                    match = line.strip().split('=')
                    if match[0] == 'CM_USERNAME' and match[1].strip().lower() in correct_matches:
                        return "yes"
    except:  # noqa: E722
        return "no"

    return "no"
